def compute(vars):
    other_long_term_liabilities = vars["v1"]
    gross_unrecognized_tax_benefits_liability = vars["v2"]

    if gross_unrecognized_tax_benefits_liability == 0:
        return None

    ratio_percentage = (
        other_long_term_liabilities
        / gross_unrecognized_tax_benefits_liability
        * 100
    )

    return {
        "value": ratio_percentage,
        "trace": {
            "other_long_term_liabilities": other_long_term_liabilities,
            "gross_unrecognized_tax_benefits_liability": gross_unrecognized_tax_benefits_liability,
            "ratio_percentage": ratio_percentage,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "percentage",
            },
        },
    }
